targetBindings.typeText:
∀ (epoch complement : ℕ),
  0 < epoch →
    epoch < complement →
      have total := ↑epoch + ↑complement;
      have boundary := (↑complement - ↑epoch) / (3 * total);
      0 < Mf.DP.binomialSkewBoundary_boundaryDoubleCumulative epoch complement (1 - boundary)

∀ (epoch complement : ℕ),
  0 < epoch + complement →
    ∀ (radius centered : ℝ),
      have total := ↑epoch + ↑complement;
      have rate := ↑epoch / total;
      have complementRate := ↑complement / total;
      have boundary := (↑complement - ↑epoch) / (3 * total);
      have steinPotential := fun value =>
        radius ^ 2 - 2 * ↑epoch * complementRate - 3 * boundary ^ 2 + value - value ^ 2;
      (centered - boundary) * ((centered - boundary) ^ 2 - radius ^ 2) - boundary * (radius ^ 2 - boundary ^ 2) =
        rate * (↑complement - centered) * steinPotential (centered + 1) -
          complementRate * (↑epoch + centered) * steinPotential centered
